// Trim, lowercase the email, and drop the obvious bots before they cost an
// LLM call. The honeypot is a hidden form field a human never fills in.
const out = [];
for (const item of $input.all()) {
  const b = item.json.body ?? item.json;
  if ((b.website ?? '').trim() !== '') continue;          // honeypot tripped
  const email = (b.email ?? '').trim().toLowerCase();
  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) continue;
  out.push({ json: {
    name: (b.name ?? '').trim(),
    email,
    brand: (b.brand ?? '').trim(),
    message: (b.message ?? '').trim().slice(0, 4000),
    budget: (b.budget ?? '').trim(),
    submittedAt: new Date().toISOString()
  }});
}
return out;

// Merge the model's verdict back onto its own enquiry. The classifier returns
// one item per input, in order, so they pair by index. If the model failed,
// or returned anything that is not a valid verdict, fall back to "unclear"
// and route to the human. Losing a lead to a bad JSON parse is the worst
// outcome here.
const ALLOWED = {
  service: ['social', 'automation', 'exec', 'unclear'],
  fit: ['strong', 'possible', 'poor'],
  urgency: ['high', 'normal']
};
const FALLBACK = { service: 'unclear', fit: 'possible', urgency: 'normal', reason: 'classifier unavailable' };
const lower = s => String(s ?? '').trim().toLowerCase();
const enquiries = $('Clean and drop bots').all();
const out = [];
$input.all().forEach((item, i) => {
  if (!enquiries[i]) return;
  let verdict = FALLBACK;
  try {
    const raw = item.json.message?.content ?? item.json.content;
    const v = typeof raw === 'string' ? JSON.parse(raw) : raw;
    const service = lower(v?.service), fit = lower(v?.fit), urgency = lower(v?.urgency);
    if (ALLOWED.service.includes(service) && ALLOWED.fit.includes(fit) && ALLOWED.urgency.includes(urgency)) {
      verdict = { service, fit, urgency, reason: String(v.reason ?? '').slice(0, 200) };
    }
  } catch (e) { /* keep the fallback */ }
  out.push({ json: { ...enquiries[i].json, ...verdict } });
});
return out;

